('q_lit-7-macha-maj_0','Kdo napsal Máj?',ARRAY['Karel Jaromír Erben','Jan Neruda','Karel Havlíček Borovský','Karel Hynek Mácha']::TEXT[],3,'Mácha, 1836.',1,ARRAY[]::TEXT[],NULL,0,'c_lit-7-macha-maj',NULL,NOW()),
