('q_lit-7-macha-maj_7','Kdy žil Karel Hynek Mácha?',ARRAY['1810–1836','1710–1760','1510–1560','1910–1960']::TEXT[],0,'Zemřel ve 25 letech.',3,ARRAY[]::TEXT[],NULL,7,'c_lit-7-macha-maj',NULL,NOW()),
('q_lit-7-macha-maj_8','Kde Mácha zemřel?',ARRAY['v Litoměřicích','v Brně','v Praze','v Plzni']::TEXT[],0,'Litoměřice.',3,ARRAY[]::TEXT[],NULL,8,'c_lit-7-macha-maj',NULL,NOW()),
